package com.ruoyi.paiflow.service;
import com.alibaba.fastjson2.*;
import java.util.*;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import okhttp3.*;
import org.springframework.stereotype.Service;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import static com.ruoyi.paiflow.service.ModelOperationJson.error;
/** HTTP正式私有出口复用已有固定DNS/TLS/no-proxy/no-redirect/no-retry设施；不启动旧Link服务。 */
@Service @ConditionalOnProperty(prefix="paiflow",name={"enabled","tools.enabled"},havingValue="true")
public class ManagedToolProducer implements ToolOperationService.Producer {
 private final ToolRuntimeCatalog catalog;private final ModelPrivateTransport transport;
 private final java.util.concurrent.ExecutorService io=new java.util.concurrent.ThreadPoolExecutor(2,2,0L,java.util.concurrent.TimeUnit.MILLISECONDS,new java.util.concurrent.SynchronousQueue<>(),r->{var t=new Thread(r,"paiflow-tool-private-http");t.setDaemon(true);return t;});
 @jakarta.annotation.PreDestroy public void close(){io.shutdownNow();}
 private final java.time.Clock clock;
 @org.springframework.beans.factory.annotation.Autowired public ManagedToolProducer(ToolRuntimeCatalog c,ModelPrivateTransport t){this(c,t,java.time.Clock.systemUTC());}
 ManagedToolProducer(ToolRuntimeCatalog c,ModelPrivateTransport t,java.time.Clock clock){catalog=c;transport=t;this.clock=clock;}
 @Override public ToolOperationService.Outcome invoke(ToolRuntimeCatalog.Fixed f,long actor,JSONObject payload){return invoke(f,actor,payload,()->true);}
 @Override public ToolOperationService.Outcome invoke(ToolRuntimeCatalog.Fixed f,long actor,JSONObject payload,java.util.function.BooleanSupplier active){var sent=new java.util.concurrent.atomic.AtomicBoolean();OkHttpClient client=null;
  try{var p=catalog.profile(f,actor);String version=catalog.credentialVersion(f,p);var message=payload.getJSONObject("payload").getJSONObject("message");var header=message.containsKey("header")?ToolSchema.decode(message.get("header")):new JSONObject();var query=message.containsKey("query")?ToolSchema.decode(message.get("query")):new JSONObject();var path=message.containsKey("path")?ToolSchema.decode(message.get("path")):new JSONObject();var body=message.containsKey("body")?ToolSchema.decode(message.get("body")):new JSONObject();
   String secret=catalog.material(f,p,version);
   var op=ToolSchema.operations(f.configuration().getJSONObject("openApiSchema")).get(f.descriptor().getString("operationId"));var authenticated=ToolHttpAuthentication.assemble(p,f.configuration(),op.method(),header,query,path,body,secret,clock.instant());URI target=authenticated.target();header=authenticated.headers();client=transport.client(target,p.getTimeoutSeconds(),p.getAllowedPrivateAddresses());var request=org.apache.http.client.methods.RequestBuilder.create(op.method()).setUri(target);header.remove("@type");for(var h:header.entrySet()){boolean privateHost="hmac".equals(ToolHttpAuthentication.mode(f.configuration()))&&"host".equalsIgnoreCase(h.getKey())&&target.getRawAuthority().equals(h.getValue());if(!(h.getValue() instanceof String value)||h.getKey().chars().anyMatch(Character::isISOControl)||value.chars().anyMatch(Character::isISOControl)||Set.of("host","content-length","transfer-encoding","connection","proxy-authorization").contains(h.getKey().toLowerCase(Locale.ROOT))&&!privateHost)throw error("工具header无效或覆盖传输边界",422);request.addHeader(h.getKey(),value);}
   String content=body.isEmpty()?null:ToolSchema.pythonJson(body);if(content!=null&&content.getBytes(StandardCharsets.UTF_8).length>p.getMaxRequestBytes())throw error("工具请求超过批准预算",413);long total=target.toASCIIString().getBytes(StandardCharsets.UTF_8).length+(content==null?0:content.getBytes(StandardCharsets.UTF_8).length);for(var h:header.entrySet())total+=h.getKey().getBytes(StandardCharsets.UTF_8).length+h.getValue().toString().getBytes(StandardCharsets.UTF_8).length+4;if(total>p.getMaxRequestBytes())throw error("工具完整请求超过批准预算",413);if(content!=null)request.setEntity(new org.apache.http.entity.StringEntity(content,org.apache.http.entity.ContentType.APPLICATION_JSON));
   catalog.profile(f,actor);if(!version.equals(catalog.credentialVersion(f,p))||!active.getAsBoolean())throw error("工具发送前许可变化",409);
   final OkHttpClient pinned=client;int timeout=p.getTimeoutSeconds()*1000;var config=org.apache.http.client.config.RequestConfig.custom().setConnectTimeout(Math.min(timeout,20000)).setSocketTimeout(timeout).setConnectionRequestTimeout(timeout).build();
   var outbound=request.build();java.util.concurrent.Future<HttpResult> future;
   try{future=io.submit(()->{if(!active.getAsBoolean()||!version.equals(catalog.credentialVersion(f,p)))throw new java.io.IOException("工具实际发送前许可变化");try(var apache=org.apache.http.impl.client.HttpClients.custom().setDefaultConnectionConfig(org.apache.http.config.ConnectionConfig.custom().setCharset(StandardCharsets.UTF_8).build()).setDefaultRequestConfig(config).disableAutomaticRetries().disableRedirectHandling().disableContentCompression().disableCookieManagement().setRoutePlanner(new org.apache.http.impl.conn.DefaultRoutePlanner(org.apache.http.impl.conn.DefaultSchemePortResolver.INSTANCE)).setDnsResolver(host->pinned.dns().lookup(host).toArray(java.net.InetAddress[]::new)).build()){sent.set(true);try(var response=apache.execute(outbound)){if(response.getEntity()==null)return new HttpResult(response.getStatusLine().getStatusCode(),"");try(var stream=response.getEntity().getContent()){byte[] bytes=stream.readNBytes(p.getMaxResponseBytes()+1);if(bytes.length>p.getMaxResponseBytes())throw new java.io.IOException("工具响应超预算");return new HttpResult(response.getStatusLine().getStatusCode(),StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(bytes)).toString());}}}});}catch(java.util.concurrent.RejectedExecutionException busy){throw error("工具私有出口容量不足",503);}
   HttpResult result;long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(p.getTimeoutSeconds());try{while(true){if(!active.getAsBoolean()||!version.equals(catalog.credentialVersion(f,p)))throw new java.io.IOException("工具许可失效，外部结果未知");long remaining=deadline-System.nanoTime();if(remaining<=0)throw new java.io.IOException("工具绝对超时");try{result=future.get(Math.min(remaining,java.util.concurrent.TimeUnit.MILLISECONDS.toNanos(500)),java.util.concurrent.TimeUnit.NANOSECONDS);break;}catch(java.util.concurrent.TimeoutException waiting){/* 等待中续核当前中心许可；本地中断不等于供应商停止。 */}}}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new java.io.IOException("工具等待中断");}catch(java.util.concurrent.ExecutionException failed){throw new java.io.IOException("工具传输失败");}finally{outbound.abort();future.cancel(true);}
   {String text=result.text();if(result.status()!=200){int code=Boolean.TRUE.equals(f.configuration().getJSONObject("openApiSchema").getJSONObject("info")==null?false:f.configuration().getJSONObject("openApiSchema").getJSONObject("info").get("x-is-official"))?30400:30403;String prefix=code==30400?"Official API request failed":"Third-party API request failed";Object errorBody;try{errorBody=JSON.parse(text);}catch(RuntimeException e){errorBody=text;}if(containsPrivateValue(errorBody,authenticated.privateValues(),p.getMaxResponseBytes()))text="[redacted]";String detail="Request error code: "+result.status()+", error message "+text;for(String value:authenticated.privateValues())if(!value.isEmpty())detail=detail.replace(value,"[redacted]");return new ToolOperationService.Outcome(envelope(f,code,prefix+": "+detail,null),"provider",true);}
    Object parsed;try{parsed=JSON.parse(text);}catch(RuntimeException e){parsed=text;}
    // 只核本次认证实际使用的私有值；JSON 转义须在解析后核对，拒绝结果不携带原文本。
    if(containsPrivateValue(parsed,authenticated.privateValues(),p.getMaxResponseBytes()))return new ToolOperationService.Outcome(null,"protocol",true);
    var responseSchema=op.schema().getJSONObject("responses").getJSONObject("200").getJSONObject("content").getJSONObject("application/json").getJSONObject("schema");try{ToolJsonSchema.response(parsed,responseSchema,f.configuration().getJSONObject("openApiSchema"));RunJsonBoundary.check(parsed,p.getMaxResponseBytes());}catch(RuntimeException e){return new ToolOperationService.Outcome(envelope(f,30202,"Response type does not match tool configuration",null),"provider",true);}
    if(containsPrivateValue(parsed,authenticated.privateValues(),p.getMaxResponseBytes()))return new ToolOperationService.Outcome(null,"protocol",true);
    return new ToolOperationService.Outcome(envelope(f,0,"Success",parsed),null,true);}
  }catch(RuntimeException|java.io.IOException e){return new ToolOperationService.Outcome(null,sent.get()?"transport":"authorization",sent.get());}finally{ModelPrivateTransport.close(client);}
 }
 private record HttpResult(int status,String text){}
 private enum NullValue { INSTANCE }
 /** 明确私有值的有界检查；不按字段名或敏感词改变业务输出，也不递归占用调用栈。 */
 private static boolean containsPrivateValue(Object value,Set<String> privateValues,int maxBytes){
  var values=privateValues.stream().filter(v->v!=null&&!v.isEmpty()).toList();if(values.isEmpty())return false;
  var pending=new ArrayDeque<Object>();pending.add(value==null?NullValue.INSTANCE:value);long nodes=0,characters=0;
  while(!pending.isEmpty()){
   Object current=pending.removeLast();if(++nodes>maxBytes)return true;
   if(current instanceof Map<?,?> map){for(var entry:map.entrySet()){if(entry.getKey()!=null){if(pending.size()>=maxBytes)return true;pending.add(entry.getKey());}if(pending.size()>=maxBytes)return true;pending.add(entry.getValue()==null?NullValue.INSTANCE:entry.getValue());}}
   else if(current instanceof Collection<?> list){for(Object item:list){if(pending.size()>=maxBytes)return true;pending.add(item==null?NullValue.INSTANCE:item);}}
   else {String text=current==NullValue.INSTANCE?"null":current instanceof String||current instanceof Number||current instanceof Boolean?current.toString():null;if(text!=null){characters+=text.length();if(characters>maxBytes)return true;for(String actual:values)if(text.contains(actual))return true;}}
  }
  return false;
 }
 static JSONObject envelope(ToolRuntimeCatalog.Fixed f,int code,String message,Object result){return JSONObject.of("header",JSONObject.of("code",code,"message",message,"sid",UUID.randomUUID().toString()),"payload",result==null?new JSONObject():JSONObject.of("text",JSONObject.of("text",ModelMessageSources.pythonJson(result))));}
 static String rawTarget(ToolRuntimeProperties.Profile p,JSONObject path){URI base=URI.create(p.getEndpoint());String url=base.toString();if(!path.isEmpty()){Object value=path.values().iterator().next();if(!(value instanceof String s))throw error("原Link首path参数不是字符串",422);var encoded=new StringBuilder();var replacements=new LinkedHashMap<String,String>();for(int offset=0;offset<s.length();offset++){char ch=s.charAt(offset);if(ch=='%'||ch==' '||ch>127){String token="__paiflow_path_"+offset+"__";if(s.contains(token)||url.contains(token))throw error("工具path占位冲突",422);encoded.append(token);replacements.put(token,String.valueOf(ch));}else encoded.append(ch);}try{url=base.resolve(encoded.toString()).toString();}catch(RuntimeException e){throw error("原Link首path参数URL无效",422);}for(var entry:replacements.entrySet())url=url.replace(entry.getKey(),entry.getValue());}
  URI target;try{target=URI.create(quote(url));}catch(RuntimeException e){throw error("原Link目标URL无效",422);}if(!Objects.equals(base.getScheme(),target.getScheme())||!Objects.equals(base.getHost(),target.getHost())||base.getPort()!=target.getPort()||target.getUserInfo()!=null||target.getFragment()!=null)throw error("工具path不能改批准出口",403);if(!path.isEmpty()&&(p.getPathPattern()==null||p.getPathPattern().length()>512||!target.getPath().matches(p.getPathPattern())))throw error("工具动态path不属于准确批准路径",403);return url;
 }
 static URI target(ToolRuntimeProperties.Profile p,JSONObject path,JSONObject query){String url=rawTarget(p,path);if(!query.isEmpty()){var pairs=new ArrayList<String>();query.forEach((k,v)->pairs.add(k+"="+ModelMessageSources.pythonString(v,false)));url+="?"+String.join("&",pairs);}return URI.create(quote(url));}
 /** Python quote(url,safe='/:?=&')；原%的再次编码与中文/空格行为保留。 */
 static String quote(String text){var out=new StringBuilder();for(byte raw:text.getBytes(StandardCharsets.UTF_8)){int c=raw&255;if(c>='a'&&c<='z'||c>='A'&&c<='Z'||c>='0'&&c<='9'||"-_.~/:?=&".indexOf(c)>=0)out.append((char)c);else out.append(String.format("%%%02X",c));}return out.toString();}
}
